from collections import deque

def get_connected_components(grid):
    """Find 4-connected components of non-background pixels"""
    components = []
    visited = set()

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == 7 and (r, c) not in visited:
                component = []
                queue = deque([(r, c)])
                while queue:
                    curr_r, curr_c = queue.popleft()
                    if (curr_r, curr_c) in visited:
                        continue
                    visited.add((curr_r, curr_c))
                    component.append((curr_r, curr_c))

                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = curr_r + dr, curr_c + dc
                        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                            if grid[nr][nc] == 7 and (nr, nc) not in visited:
                                queue.append((nr, nc))
                components.append(component)

    return components

components = get_connected_components(grid)
print(f"Found {len(components)} connected components:")
